public Optional<SparkImage> resolveImage(String type, String version) {
    if (sparkImages == null || sparkImages.isEmpty()) {
        return Optional.empty();
    }
    return sparkImages.stream().filter(t -> typeMatch(t.types, type) && t.version != null && t.version.equalsIgnoreCase(version)).findFirst();
}
